package objects

import (
	"strings"

	wire "template/contracts-go/wire"
)

// PostalAddress is the canonical shipping/billing address shape per
// spec § BC4 Sales. Every field is optional — providers vary
// dramatically in what they collect; an Order can legally have no
// shipping address (digital goods).
//
// CountryCode is the only country representation the canonical layer
// keeps: a normalised ISO 3166-1 alpha-2 code typed against the wire
// Country enum. Providers send a free-form country *name* alongside the
// raw code; the normalizer collapses both into this single typed field
// via NormalizeCountryCode, so the aggregate never stores an unparsed
// provider string. Contact phone lives on the Order (CustomerPhoneNumber),
// not on the address.
type PostalAddress struct {
	Line1        *string
	Line2        *string
	City         *string
	Province     *string
	ProvinceCode *string
	ZipCode      *string
	CountryCode  *wire.Country
	Latitude     *float64
	Longitude    *float64
}

// NormalizeCountryCode coerces a provider-supplied country code into the
// wire Country enum. It trims surrounding whitespace and upper-cases the
// input before validating against the enum catalog; an empty/nil input or
// anything outside the supported markets yields nil rather than an error —
// an unsupported country is "no country", not a hard failure that should
// reject the whole order.
func NormalizeCountryCode(raw *string) *wire.Country {
	if raw == nil {
		return nil
	}
	code := strings.ToUpper(strings.TrimSpace(*raw))
	if code == "" {
		return nil
	}
	c, err := wire.ParseCountry(code)
	if err != nil {
		return nil
	}
	return &c
}

