package objects

// PostalAddress is the canonical shipping/billing address shape per
// spec § BC4 Sales. Every field is optional — providers vary
// dramatically in what they collect; an Order can legally have no
// shipping address (digital goods).
//
// No validation in the constructor beyond "the struct exists" — the
// canonical layer doesn't normalise countries or zip codes (that's
// downstream concern). The aggregate just preserves whatever the
// normalizer extracted from the provider payload.
type PostalAddress struct {
	Line1        *string
	Line2        *string
	City         *string
	Province     *string
	ProvinceCode *string
	ZipCode      *string
	Country      *string
	CountryCode  *string
	Latitude     *float64
	Longitude    *float64
	PhoneNumber  *string
}

package shopify

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"time"

	"template/api-go/internal/sync/entities"
	"template/api-go/internal/sync/objects"
	"template/api-go/internal/sync/services/pipelines"
	wire "template/contracts-go/wire"
)

// PlatformID is the wire enum value all Shopify normalisers register
// under. Mirrors `wire.SalesPlatformSHOPIFY`.
const PlatformID = string(wire.SalesPlatformSHOPIFY)

// OrdersNormalizer maps a raw Shopify Order JSON to
// entities.OrderInput. Pulled from the Shopify REST Admin API's
// `/admin/api/<v>/orders.json` payload format.
type OrdersNormalizer struct{}

func NewOrdersNormalizer() *OrdersNormalizer { return &OrdersNormalizer{} }

func (n *OrdersNormalizer) Platform() string { return PlatformID }

// rawShopifyOrder is the subset of Shopify's Order payload the
// canonical mapping needs. Unmapped fields are intentionally
// dropped — adding them later just means adding a struct field +
// touching the mapping body, not re-shaping the canonical aggregate.
type rawShopifyOrder struct {
	ID              int64                `json:"id"`
	CreatedAt       string               `json:"created_at"`
	Currency        string               `json:"currency"`
	TotalPrice      string               `json:"total_price"`
	SubtotalPrice   string               `json:"subtotal_price"`
	TotalTax        string               `json:"total_tax"`
	TotalDiscounts  string               `json:"total_discounts"`
	FinancialStatus string               `json:"financial_status"`
	PaymentGateway  []string             `json:"payment_gateway_names"`
	CartToken       *string              `json:"cart_token,omitempty"`
	Note            *string              `json:"note,omitempty"`
	Email           *string              `json:"email,omitempty"`
	Phone           *string              `json:"phone,omitempty"`
	Customer        *rawShopifyCustomer  `json:"customer,omitempty"`
	ShippingAddress *rawShopifyAddress   `json:"shipping_address,omitempty"`
	LineItems       []rawShopifyLineItem `json:"line_items"`

	// `total_shipping_price_set` is nested; we capture it directly to
	// avoid an extra-nested struct just for one field.
	TotalShippingPriceSet *rawShopifyMoneySet `json:"total_shipping_price_set,omitempty"`

	// `total_price_set` carries both shop-currency and presentment-
	// currency totals for multi-currency orders.
	TotalPriceSet *rawShopifyMoneySet `json:"total_price_set,omitempty"`

	// `note_attributes` is an array of {name, value} pairs. Shopify
	// uses it to carry UTM attribution, pixel IDs, and other checkout
	// meta injected by storefronts / partner apps.
	NoteAttributes []struct {
		Name  string `json:"name"`
		Value string `json:"value"`
	} `json:"note_attributes,omitempty"`
}

type rawShopifyCustomer struct {
	FirstName *string `json:"first_name,omitempty"`
	LastName  *string `json:"last_name,omitempty"`
	Phone     *string `json:"phone,omitempty"`
}

type rawShopifyAddress struct {
	Address1     *string  `json:"address1,omitempty"`
	Address2     *string  `json:"address2,omitempty"`
	City         *string  `json:"city,omitempty"`
	Province     *string  `json:"province,omitempty"`
	ProvinceCode *string  `json:"province_code,omitempty"`
	Zip          *string  `json:"zip,omitempty"`
	Country      *string  `json:"country,omitempty"`
	CountryCode  *string  `json:"country_code,omitempty"`
	Latitude     *float64 `json:"latitude,omitempty"`
	Longitude    *float64 `json:"longitude,omitempty"`
	Phone        *string  `json:"phone,omitempty"`
}

type rawShopifyMoney struct {
	Amount       string `json:"amount"`
	CurrencyCode string `json:"currency_code"`
}

type rawShopifyMoneySet struct {
	ShopMoney        rawShopifyMoney  `json:"shop_money"`
	PresentmentMoney *rawShopifyMoney `json:"presentment_money,omitempty"`
}

type rawShopifyLineItem struct {
	ID            int64  `json:"id"`
	ProductID     *int64 `json:"product_id,omitempty"`
	VariantID     *int64 `json:"variant_id,omitempty"`
	Quantity      int    `json:"quantity"`
	Price         string `json:"price"` // unit price
	TotalDiscount string `json:"total_discount"`
	TaxLines      []struct {
		Price string `json:"price"`
	} `json:"tax_lines,omitempty"`
}

// Normalize parses + maps the raw payload. Wrap-errors with
// `ErrNormalizerBadPayload` so the pipeline can skip + continue.
func (n *OrdersNormalizer) Normalize(raw []byte, in pipelines.RunInput) (entities.OrderInput, error) {
	var ro rawShopifyOrder
	if err := json.Unmarshal(raw, &ro); err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: %v", ErrNormalizerBadPayload, err)
	}
	if ro.ID == 0 {
		return entities.OrderInput{}, fmt.Errorf("%w: missing id", ErrNormalizerBadPayload)
	}

	createdAt, err := parseShopifyTime(ro.CreatedAt)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: created_at: %v", ErrNormalizerBadPayload, err)
	}

	subtotalCents, err := parseDecimalToCents(ro.SubtotalPrice)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: subtotal_price: %v", ErrNormalizerBadPayload, err)
	}
	taxCents, err := parseDecimalToCents(ro.TotalTax)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: total_tax: %v", ErrNormalizerBadPayload, err)
	}
	discountCents, err := parseDecimalToCents(ro.TotalDiscounts)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: total_discounts: %v", ErrNormalizerBadPayload, err)
	}
	totalCents, err := parseDecimalToCents(ro.TotalPrice)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: total_price: %v", ErrNormalizerBadPayload, err)
	}
	shippingCents := int64(0)
	if ro.TotalShippingPriceSet != nil {
		shippingCents, err = parseDecimalToCents(ro.TotalShippingPriceSet.ShopMoney.Amount)
		if err != nil {
			return entities.OrderInput{}, fmt.Errorf("%w: shipping: %v", ErrNormalizerBadPayload, err)
		}
	}

	currency := ro.Currency
	subtotalMA, err := objects.NewMonetaryAmount(subtotalCents, currency)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: subtotal currency: %v", ErrNormalizerBadPayload, err)
	}
	taxMA, _ := objects.NewMonetaryAmount(taxCents, currency)
	discountMA, _ := objects.NewMonetaryAmount(discountCents, currency)
	totalMA, _ := objects.NewMonetaryAmount(totalCents, currency)
	shippingMA, _ := objects.NewMonetaryAmount(shippingCents, currency)

	gateway := "UNKNOWN"
	if len(ro.PaymentGateway) > 0 {
		gateway = strings.ToUpper(ro.PaymentGateway[0])
	}

	externalID := strconv.FormatInt(ro.ID, 10)

	// Lines — normalised inline (one mapping for the canonical
	// constructor's per-line invariants).
	lines := make([]entities.OrderLine, 0, len(ro.LineItems))
	for _, rawItem := range ro.LineItems {
		line, lineErr := mapLineItem(rawItem, externalID, currency)
		if lineErr != nil {
			return entities.OrderInput{}, fmt.Errorf("%w: line item %d: %v", ErrNormalizerBadPayload, rawItem.ID, lineErr)
		}
		lines = append(lines, line)
	}

	// Customer name from first + last.
	var customerName *string
	if ro.Customer != nil {
		full := strings.TrimSpace(joinPointer(ro.Customer.FirstName, " ", ro.Customer.LastName))
		if full != "" {
			customerName = &full
		}
	}

	var shipping *objects.PostalAddress
	if ro.ShippingAddress != nil {
		shipping = &objects.PostalAddress{
			Line1:        ro.ShippingAddress.Address1,
			Line2:        ro.ShippingAddress.Address2,
			City:         ro.ShippingAddress.City,
			Province:     ro.ShippingAddress.Province,
			ProvinceCode: ro.ShippingAddress.ProvinceCode,
			ZipCode:      ro.ShippingAddress.Zip,
			Country:      ro.ShippingAddress.Country,
			CountryCode:  ro.ShippingAddress.CountryCode,
			Latitude:     ro.ShippingAddress.Latitude,
			Longitude:    ro.ShippingAddress.Longitude,
			PhoneNumber:  ro.ShippingAddress.Phone,
		}
	}

	// UTM extraction — walk note_attributes for utm_* keys.
	// Non-UTM keys (fbc, fbp, ttp…) are ignored intentionally.
	// UtmTags is only allocated when at least one UTM field is present.
	var utm *objects.UtmTags
	for _, attr := range ro.NoteAttributes {
		v := attr.Value
		if v == "" {
			continue
		}
		switch strings.ToLower(attr.Name) {
		case "utm_source":
			if utm == nil {
				utm = &objects.UtmTags{}
			}
			utm.Source = &v
		case "utm_medium":
			if utm == nil {
				utm = &objects.UtmTags{}
			}
			utm.Medium = &v
		case "utm_campaign":
			if utm == nil {
				utm = &objects.UtmTags{}
			}
			utm.Campaign = &v
		case "utm_term":
			if utm == nil {
				utm = &objects.UtmTags{}
			}
			utm.Term = &v
		case "utm_content":
			if utm == nil {
				utm = &objects.UtmTags{}
			}
			utm.Content = &v
		}
	}

	// Presentment money — extracted from total_price_set.presentment_money
	// when the presentment currency differs from the shop currency (or
	// even when it matches — always capture when present).
	var presentmentMoney *objects.MonetaryAmount
	if ro.TotalPriceSet != nil && ro.TotalPriceSet.PresentmentMoney != nil {
		pm := ro.TotalPriceSet.PresentmentMoney
		if pm.Amount != "" && pm.CurrencyCode != "" {
			pmCents, pmErr := parseDecimalToCents(pm.Amount)
			if pmErr == nil {
				// Best-effort: if the currency is unrecognised we skip
				// silently rather than failing the whole order.
				if ma, maErr := objects.NewMonetaryAmount(pmCents, pm.CurrencyCode); maErr == nil {
					presentmentMoney = &ma
				}
			}
		}
	}

	return entities.OrderInput{
		Platform:                   PlatformID,
		ExternalID:                 externalID,
		ExternalCreatedAt:          createdAt,
		StoreID:                    in.StoreID,
		StoreIntegrationID:         in.StoreIntegrationID,
		StoreIntegrationExternalID: in.StoreIntegrationExternalID,
		Description:                ro.Note,
		CustomerEmail:              ro.Email,
		CustomerName:               customerName,
		CustomerPhoneNumber: func() *string {
			if ro.Customer != nil && ro.Customer.Phone != nil {
				return ro.Customer.Phone
			}
			return ro.Phone
		}(),
		ShippingAddress: shipping,
		Subtotal:        subtotalMA,
		DiscountTotal:   discountMA,
		ShippingTotal:   shippingMA,
		TaxTotal:        taxMA,
		Total:           totalMA,
		PaymentStatus:   mapFinancialStatus(ro.FinancialStatus),
		PaymentMethod:   string(wire.PaymentMethodCREDIT_CARD), // Shopify rarely exposes per-order payment method; default
		PaymentGateway:  mapGateway(gateway),
		Lines:            lines,
		Transactions:     nil, // Shopify's /transactions.json is a separate pull; iter 283+
		CartToken:        ro.CartToken,
		Utm:              utm,
		PresentmentMoney: presentmentMoney,
		IsDraft:          false,
		IsManual:         false,
	}, nil
}

func mapLineItem(raw rawShopifyLineItem, orderExternalID string, currency string) (entities.OrderLine, error) {
	unitPriceCents, err := parseDecimalToCents(raw.Price)
	if err != nil {
		return entities.OrderLine{}, err
	}
	discountCents, err := parseDecimalToCents(raw.TotalDiscount)
	if err != nil {
		return entities.OrderLine{}, err
	}
	taxCents := int64(0)
	for _, t := range raw.TaxLines {
		c, terr := parseDecimalToCents(t.Price)
		if terr != nil {
			return entities.OrderLine{}, terr
		}
		taxCents += c
	}
	subtotalCents := unitPriceCents * int64(raw.Quantity)
	totalCents := subtotalCents - discountCents
	subtotalPrice, _ := objects.NewMonetaryAmount(subtotalCents, currency)
	discount, _ := objects.NewMonetaryAmount(discountCents, currency)
	tax, _ := objects.NewMonetaryAmount(taxCents, currency)
	total, _ := objects.NewMonetaryAmount(totalCents, currency)

	productExt := ""
	if raw.ProductID != nil {
		productExt = strconv.FormatInt(*raw.ProductID, 10)
	}
	variantExt := ""
	if raw.VariantID != nil {
		variantExt = strconv.FormatInt(*raw.VariantID, 10)
	}

	return entities.NewOrderLine(entities.OrderLineInput{
		Platform:          PlatformID,
		OrderExternalID:   orderExternalID,
		ExternalLineID:    strconv.FormatInt(raw.ID, 10),
		ProductExternalID: productExt,
		VariantExternalID: variantExt,
		Quantity:          raw.Quantity,
		SubtotalPrice:     subtotalPrice,
		Discount:          discount,
		Tax:               tax,
		TotalPrice:        total,
	})
}

func parseShopifyTime(s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, fmt.Errorf("empty")
	}
	return time.Parse(time.RFC3339, s)
}

// parseDecimalToCents converts "100.50" → 10050. Tolerates missing
// fractional part ("100" → 10000) and a single decimal digit
// ("100.5" → 10050).
func parseDecimalToCents(s string) (int64, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, nil
	}
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	parts := strings.SplitN(s, ".", 2)
	whole, err := strconv.ParseInt(parts[0], 10, 64)
	if err != nil {
		return 0, err
	}
	cents := whole * 100
	if len(parts) == 2 {
		frac := parts[1]
		switch len(frac) {
		case 0:
			// "100." — treat as whole
		case 1:
			d, err := strconv.ParseInt(frac, 10, 64)
			if err != nil {
				return 0, err
			}
			cents += d * 10
		default:
			d, err := strconv.ParseInt(frac[:2], 10, 64)
			if err != nil {
				return 0, err
			}
			cents += d
		}
	}
	if neg {
		cents = -cents
	}
	return cents, nil
}

func mapFinancialStatus(s string) string {
	switch strings.ToLower(s) {
	case "paid":
		return string(wire.PaymentStatusPAID)
	case "partially_paid":
		return string(wire.PaymentStatusPARTIALLY_PAID)
	case "pending":
		return string(wire.PaymentStatusPENDING)
	case "authorized":
		return string(wire.PaymentStatusAUTHORIZED)
	case "refunded":
		return string(wire.PaymentStatusREFUNDED)
	case "partially_refunded":
		return string(wire.PaymentStatusPARTIALLY_REFUNDED)
	case "voided":
		return string(wire.PaymentStatusVOIDED)
	case "unpaid":
		return string(wire.PaymentStatusUNPAID)
	default:
		return string(wire.PaymentStatusPENDING)
	}
}

func mapGateway(s string) string {
	switch strings.ToUpper(s) {
	case "STRIPE":
		return string(wire.PaymentGatewaySTRIPE)
	case "SHOPIFY_PAYMENTS", "BOGUS":
		return string(wire.PaymentGatewaySHOPIFY_PAYMENTS)
	case "PAYPAL":
		return string(wire.PaymentGatewayPAYPAL)
	case "MERCADOPAGO":
		return string(wire.PaymentGatewayMERCADOPAGO)
	case "APPMAX":
		return string(wire.PaymentGatewayAPPMAX)
	case "PAGAR_ME":
		return string(wire.PaymentGatewayPAGAR_ME)
	case "YEVER":
		return string(wire.PaymentGatewayYEVER)
	default:
		return string(wire.PaymentGatewayUNKNOWN)
	}
}

func joinPointer(a *string, sep string, b *string) string {
	first := ""
	if a != nil {
		first = *a
	}
	second := ""
	if b != nil {
		second = *b
	}
	if first == "" {
		return second
	}
	if second == "" {
		return first
	}
	return first + sep + second
}

