		return string(wire.PaymentGatewayPAGAR_ME)
	case "YEVER":
		return string(wire.PaymentGatewayYEVER)
	default:
		return string(wire.PaymentGatewayUNKNOWN)
	}
}

func joinPointer(a *string, sep string, b *string) string {
	first := ""
	if a != nil {
		first = *a
	}
	second := ""
	if b != nil {
		second = *b
	}
	if first == "" {
		return second
	}
	if second == "" {
		return first
	}
	return first + sep + second
}

// compile-time interface check
var _ OrderNormalizer = (*OrdersNormalizer)(nil)

