	wire "template/contracts-go/wire"
	"template/core-go/types"
)

// AdAccountsPipeline implements AD_ACCOUNTS for GOOGLE_ADS.
//
// For Google Ads, the "ad account" is the customer account (customerID).
// The loginCustomerID (MCC) is the parent BusinessAccount when present.
// We emit one ExternalAdAccountUpdated event for the customer account,
// plus a wire discovery event for the TS link table (Spec β.2).
type AdAccountsPipeline struct{}

// NewGoogleAdAccountsPipeline constructs the pipeline.
func NewGoogleAdAccountsPipeline() *AdAccountsPipeline {
	return &AdAccountsPipeline{}
}

func (p *AdAccountsPipeline) Platform() wire.SalesPlatform { return "GOOGLE_ADS" }
func (p *AdAccountsPipeline) Pipeline() enums.SyncPipelineName {
	return enums.SyncPipelineAdAccounts
}

func (p *AdAccountsPipeline) Run(ctx context.Context, in pipelines.RunInput, publisher pipelines.ExternalEventPublisher) (pipelines.RunResult, error) {
	refreshToken := in.Credentials["refreshToken"]
	customerID := in.Credentials["customerId"]
	loginCustomerID := in.Credentials["loginCustomerId"]

	if refreshToken == "" {
		return pipelines.RunResult{Succeeded: false, ErrorMsg: "google_ads credential 'refreshToken' is missing"},
			fmt.Errorf("google_ads ad_accounts: refreshToken required")
	}
	if customerID == "" {
		return pipelines.RunResult{Succeeded: false, ErrorMsg: "google_ads credential 'customerId' is missing"},
			fmt.Errorf("google_ads ad_accounts: customerId required")
	}

	client := googlesvc.NewClient(googlesvc.ClientConfig{})

	// Fetch customer info to get currency, timezone, and name.
	customerInfo, err := client.GetCustomerInfo(ctx, refreshToken, customerID, loginCustomerID)
	if err != nil {
		return pipelines.RunResult{Succeeded: false, ErrorMsg: err.Error()},
			fmt.Errorf("google_ads ad_accounts: GetCustomerInfo: %w", err)
	}

	// The parent BusinessAccount is the MCC (loginCustomerID) when present.
	businessAccountExternalID := loginCustomerID
	if businessAccountExternalID == "" {
		businessAccountExternalID = customerID
	}

	accountName := customerInfo.DescriptiveName
	if accountName == "" {
		accountName = customerID
	}

	input := entities.AdAccountInput{
		Platform:                  "GOOGLE_ADS",
		ExternalID:                customerID,
		BusinessAccountExternalID: businessAccountExternalID,
		Name:                      accountName,
		Currency:                  customerInfo.CurrencyCode,
		Timezone:                  customerInfo.TimeZone,
		Status:                    "ACTIVE",
		ExternalCreatedAt:         time.Time{},
	}

	// 1. Emit domain event → handler persists the aggregate
	evt := events.NewExternalAdAccountUpdated(input, in.StoreID)
	if err := publisher.Publish(ctx, evt); err != nil {
		return pipelines.RunResult{Succeeded: false, ErrorMsg: err.Error()},
			fmt.Errorf("google_ads ad_accounts: publish domain event: %w", err)
	}

	// 2. Publish wire discovery event for TS link table (Spec β.2)
	discoveryEvt := buildGoogleAdAccountDiscoveryEvent(in, customerInfo, customerID, businessAccountExternalID)
	if in.Mediator != nil {
		if pubErr := in.Mediator.Publish(ctx, discoveryEvt); pubErr != nil {
			// Non-fatal — domain event already persisted.
			_ = pubErr
		}
	}

	return pipelines.RunResult{RowsTouched: 1, Succeeded: true}, nil
}

func buildGoogleAdAccountDiscoveryEvent(
	in pipelines.RunInput,
	customerInfo *googlesvc.CustomerResponse,
	adAccountExternalID,
	businessAccountExternalID string,
) types.IntegrationEvent[wire.MarketingAdAccountDiscoveredEvent] {
	currency, _ := wire.ParseCurrencyCode(customerInfo.CurrencyCode)
	accountName := customerInfo.DescriptiveName
	if accountName == "" {
		accountName = adAccountExternalID
	}

	payload := wire.MarketingAdAccountDiscoveredEvent{
		Name:                       wire.MarketingAdAccountDiscoveredEventName,
		OwnerID:                    in.StoreID,
		OccurredAt:                 time.Now().UTC(),
		Platform:                   wire.MarketingPlatformGOOGLE_ADS,
		AdAccountExternalID:        adAccountExternalID,
		BusinessAccountExternalID:  businessAccountExternalID,
		AccountName:                accountName,
		StoreIntegrationExternalID: in.StoreIntegrationExternalID,
		Currency:                   currency,
	}
	return types.NewIntegrationEvent(wire.MarketingAdAccountDiscoveredEventName, in.StoreID, payload)
}

// compile-time check
var _ pipelines.Pipeline = (*AdAccountsPipeline)(nil)

package google

import (
	"log/slog"
	"time"

	"template/api-go/internal/sync/entities"
)

// MarketingMetricNormalizerInput is the input to NormalizeAdSpends.
type MarketingMetricNormalizerInput struct {
	Rows         []GoogleAdsRow
	CustomerInfo *CustomerResponse
	GroupBy      string // "DAILY" or "HOURLY"
}

// NormalizeAdSpends converts Google Ads GAQL rows to entities.AdSpendInput slices
// aggregated per (adAccount, campaign, bucketStart, groupBy).
//
// Google's cost is reported in micro-units (1_000_000 micros = 1 currency unit).
// We convert to cents: costMicros / 10_000 (rounded).
func NormalizeAdSpends(input *MarketingMetricNormalizerInput) []entities.AdSpendInput {
	timezone := customerTimezone(input.CustomerInfo)
	currency := customerCurrency(input.CustomerInfo)
	customerID := customerExternalID(input.CustomerInfo)

	groupBy := input.GroupBy
	if groupBy == "" {
		groupBy = "DAILY"
	}

	out := make([]entities.AdSpendInput, 0, len(input.Rows))
	for _, row := range input.Rows {
		spendCents := costMicrosToCents(row.Metrics.CostMicros)
		if spendCents == 0 {
			continue // skip zero-spend rows
		}

		var startDate, endDate time.Time
		if groupBy == "DAILY" {
			startDate, endDate = parseDailyTimeRange(&row, timezone)
		} else {
			startDate, endDate = parseHourlyTimeRange(&row, timezone)
		}

		out = append(out, entities.AdSpendInput{
			Platform:            "GOOGLE_ADS",
			AdAccountExternalID: customerID,
			CampaignExternalID:  row.Campaign.ID,
			Currency:            currency,
			StartDate:           startDate.UTC(),
			EndDate:             endDate.UTC(),
			GroupBy:             groupBy,
			SpendCents:          spendCents,
		})
	}
	return out
}

// CustomerTimezoneForInfo is the exported timezone resolver used by pipelines.
func CustomerTimezoneForInfo(info *CustomerResponse) *time.Location {
	return customerTimezone(info)
}

// GenerateDaysInLocation returns a list of days (newest first) within [start, end]
// expressed in the given location.
func GenerateDaysInLocation(start, end time.Time, loc *time.Location) []time.Time {
	startDay := time.Date(start.Year(), start.Month(), start.Day(), 0, 0, 0, 0, loc)
	endDay := time.Date(end.Year(), end.Month(), end.Day(), 0, 0, 0, 0, loc)

	var days []time.Time
	for d := endDay; !d.Before(startDay); d = d.AddDate(0, 0, -1) {
		days = append(days, d)
	}
	return days
}

// --- Internal helpers ---

func parseDailyTimeRange(row *GoogleAdsRow, loc *time.Location) (time.Time, time.Time) {
	base, err := time.ParseInLocation("2006-01-02", row.Segments.Date, loc)
	if err != nil {
		slog.Warn("google: failed to parse daily date, falling back to now",
			"value", row.Segments.Date, "error", err)
		now := time.Now().In(loc)
		return now, now
	}
	return base, base.Add(24*time.Hour - time.Second)
}

func parseHourlyTimeRange(row *GoogleAdsRow, loc *time.Location) (time.Time, time.Time) {
	base, err := time.ParseInLocation("2006-01-02", row.Segments.Date, loc)
	if err != nil {
		slog.Warn("google: failed to parse hourly date, falling back to now",
			"value", row.Segments.Date, "error", err)
		now := time.Now().In(loc)
		return now, now
	}
	startDate := base.Add(time.Duration(row.Segments.Hour) * time.Hour)
	endDate := startDate.Add(time.Hour - time.Second)

	endDate := startDate.Add(time.Hour - time.Second)
	return startDate, endDate
}

// costMicrosToCents converts Google Ads cost_micros to cents (round-half-up).
// 1_000_000 micros = 1 currency unit = 100 cents → divide by 10_000.
func costMicrosToCents(costMicros int64) int64 {
	if costMicros >= 0 {
		return (costMicros + 5000) / 10000
	}
	return (costMicros - 5000) / 10000
}

func customerTimezone(info *CustomerResponse) *time.Location {
	if info == nil || info.TimeZone == "" {
		return time.UTC
	}
	loc, err := time.LoadLocation(info.TimeZone)
	if err != nil {
		slog.Warn("google: failed to load timezone, defaulting to UTC",
			"timezone", info.TimeZone, "error", err)
		return time.UTC
	}
	return loc
}

func customerCurrency(info *CustomerResponse) string {
	if info == nil || info.CurrencyCode == "" {
		return "USD"
	}
	return info.CurrencyCode
}

func customerExternalID(info *CustomerResponse) string {
	if info == nil {
		return ""
	}
	return info.ID
}

