package facebook

import (
	"context"
	"fmt"
	"time"

	"template/api-go/internal/sync/entities"
	"template/api-go/internal/sync/enums"
	"template/api-go/internal/sync/events"
	"template/api-go/internal/sync/services/facebook"
	"template/api-go/internal/sync/services/pipelines"
	wire "template/contracts-go/wire"
	"template/core-go/types"
)

// AdAccountsPipeline implements AD_ACCOUNTS for META.
// It lists all Business Manager accounts first, then for each BM discovers all
// owned ad accounts, emits ExternalAdAccountUpdated for each ad account, and
// also publishes a MarketingAdAccountDiscoveredEvent wire event so the TS link
// table (Spec β.2) can create the association.
type AdAccountsPipeline struct{}

// NewFacebookAdAccountsPipeline constructs the pipeline.
func NewFacebookAdAccountsPipeline() *AdAccountsPipeline {
	return &AdAccountsPipeline{}
}

func (p *AdAccountsPipeline) Platform() wire.SalesPlatform    { return "META" }
func (p *AdAccountsPipeline) Pipeline() enums.SyncPipelineName {
	return enums.SyncPipelineAdAccounts
}

func (p *AdAccountsPipeline) Run(ctx context.Context, in pipelines.RunInput, publisher pipelines.ExternalEventPublisher) (pipelines.RunResult, error) {
	accessToken := in.Credentials["accessToken"]
	if accessToken == "" {
		return pipelines.RunResult{Succeeded: false, ErrorMsg: "facebook credential 'accessToken' is missing"},
			fmt.Errorf("facebook ad_accounts: accessToken required")
	}

	client := facebook.NewClient(facebook.ClientConfig{})
	rowsTouched := 0

	// Step 1: Enumerate Business Manager accounts
	bmResp, err := client.GetOwnedBusinessAccounts(ctx, accessToken)
	if err != nil {
		return pipelines.RunResult{RowsTouched: rowsTouched, Succeeded: false, ErrorMsg: err.Error()},
			fmt.Errorf("facebook ad_accounts: fetch business accounts: %w", err)
	}

	for {
		for _, bm := range bmResp.Data {
			// Step 2: For each BM, enumerate its owned ad accounts
			aaResp, err := client.GetAdAccountsForBusiness(ctx, accessToken, bm.ID)
			if err != nil {
				return pipelines.RunResult{RowsTouched: rowsTouched, Succeeded: false, ErrorMsg: err.Error()},
					fmt.Errorf("facebook ad_accounts: fetch ad accounts for business %s: %w", bm.ID, err)
			}

			for {
				for _, aa := range aaResp.Data {
					input := entities.AdAccountInput{
						Platform:                  "META",
						ExternalID:                aa.ID,
						BusinessAccountExternalID: bm.ID,
						Name:                      aa.Name,
						Currency:                  aa.Currency,
						Timezone:                  aa.TimezoneName,
						Status:                    mapAdAccountStatus(aa.AccountStatus),
						ExternalCreatedAt:         time.Time{},
					}

					// 1. Emit domain event → handler persists the aggregate
					evt := events.NewExternalAdAccountUpdated(input, in.StoreID)
					if err := publisher.Publish(ctx, evt); err != nil {
						return pipelines.RunResult{RowsTouched: rowsTouched, Succeeded: false, ErrorMsg: err.Error()},
							fmt.Errorf("facebook ad_accounts: publish domain event: %w", err)
					}

					// 2. Publish wire discovery event for TS link table (Spec β.2)
					discoveryEvt := buildAdAccountDiscoveryEvent(in, aa, bm.ID)
					if in.Mediator != nil {
						if pubErr := in.Mediator.Publish(ctx, discoveryEvt); pubErr != nil {
							// Non-fatal — domain event already persisted.
							_ = pubErr
						}
					}

					rowsTouched++
				}

				if aaResp.Paging == nil || aaResp.Paging.Next == "" {
					break
				}
				next, err := client.FetchNextAdAccountsPage(ctx, aaResp.Paging.Next)
				if err != nil {
					return pipelines.RunResult{RowsTouched: rowsTouched, Succeeded: false, ErrorMsg: err.Error()},
						fmt.Errorf("facebook ad_accounts: next ad accounts page: %w", err)
				}
				aaResp = next
			}
		}

		if bmResp.Paging == nil || bmResp.Paging.Next == "" {
			break
		}
		nextBM, err := client.FetchNextBusinessAccountsPage(ctx, bmResp.Paging.Next)
		if err != nil {
			return pipelines.RunResult{RowsTouched: rowsTouched, Succeeded: false, ErrorMsg: err.Error()},
				fmt.Errorf("facebook ad_accounts: next business accounts page: %w", err)
		}
		bmResp = nextBM
	}

	return pipelines.RunResult{RowsTouched: rowsTouched, Succeeded: true}, nil
}

// mapAdAccountStatus converts the numeric Facebook account_status to a canonical string.
// See: https://developers.facebook.com/docs/marketing-api/reference/ad-account
func mapAdAccountStatus(status int) string {
	switch status {
	case 1:
		return "ACTIVE"
	case 2:
		return "DISABLED"
	case 3:
		return "UNSETTLED"
	case 7:
		return "PENDING_RISK_REVIEW"
	case 8:
		return "PENDING_SETTLEMENT"
	case 9:
		return "IN_GRACE_PERIOD"
	case 100:
		return "PENDING_CLOSURE"
	case 101:
		return "CLOSED"
	case 201:
		return "ANY_ACTIVE"
	case 202:
		return "ANY_CLOSED"
	default:
		return "ACTIVE"
	}
}

func buildAdAccountDiscoveryEvent(in pipelines.RunInput, aa facebook.FacebookAdAccount, businessAccountExternalID string) types.IntegrationEvent[wire.MarketingAdAccountDiscoveredEvent] {
	currency, _ := wire.ParseCurrencyCode(aa.Currency)
	payload := wire.MarketingAdAccountDiscoveredEvent{
		Name:                       wire.MarketingAdAccountDiscoveredEventName,
		OwnerID:                    in.StoreID,
		OccurredAt:                 time.Now().UTC(),
		Platform:                   wire.MarketingPlatformMETA,
		AdAccountExternalID:        aa.ID,
		BusinessAccountExternalID:  businessAccountExternalID,
		AccountName:                aa.Name,
		StoreIntegrationExternalID: in.StoreIntegrationExternalID,
		Currency:                   currency,
	}
	return types.NewIntegrationEvent(wire.MarketingAdAccountDiscoveredEventName, in.StoreID, payload)
}

// compile-time check
var _ pipelines.Pipeline = (*AdAccountsPipeline)(nil)

package facebook

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"time"
)

const (
	DefaultAPIVersion = "v21.0"
	BaseURL           = "https://graph.facebook.com"
)

// Client is the Facebook Marketing API HTTP client.
type Client struct {
	apiVersion  string
	httpClient  *http.Client
	testBaseURL string // populated only via SetBaseURLForTest
}

// ClientConfig allows overriding defaults at construction time.
type ClientConfig struct {
	APIVersion string
	Timeout    time.Duration
}

// NewClient constructs a Client with sensible defaults.
func NewClient(cfg ClientConfig) *Client {
	apiVersion := cfg.APIVersion
	if apiVersion == "" {
		apiVersion = DefaultAPIVersion
	}
	timeout := cfg.Timeout
	if timeout == 0 {
		timeout = 30 * time.Second
	}
	return &Client{
		apiVersion: apiVersion,
		httpClient: &http.Client{Timeout: timeout},
	}
}

// SetBaseURLForTest overrides the upstream host. Must not be called in production.
func (c *Client) SetBaseURLForTest(u string) { c.testBaseURL = u }

func (c *Client) baseURL() string {
	if c.testBaseURL != "" {
		return fmt.Sprintf("%s/%s", c.testBaseURL, c.apiVersion)
	}
	return fmt.Sprintf("%s/%s", BaseURL, c.apiVersion)
