package tiktok

import (
	"context"
	"fmt"
	"time"

	"template/api-go/internal/sync/entities"
	"template/api-go/internal/sync/enums"
	"template/api-go/internal/sync/events"
	"template/api-go/internal/sync/services/pipelines"
	tiktoksvc "template/api-go/internal/sync/services/tiktok"
	wire "template/contracts-go/wire"
	"template/core-go/types"
)

// AdAccountsPipeline implements AD_ACCOUNTS for TIKTOK.
//
// TikTok's model: the advertiser_id IS the ad account. We fetch advertiser
// info (currency, timezone) from the API and emit ExternalAdAccountUpdated +
// MarketingAdAccountDiscoveredEvent so the TS link table can create the
// association.
type AdAccountsPipeline struct{}

// NewTikTokAdAccountsPipeline constructs the pipeline.
func NewTikTokAdAccountsPipeline() *AdAccountsPipeline {
	return &AdAccountsPipeline{}
}

func (p *AdAccountsPipeline) Platform() wire.SalesPlatform    { return "TIKTOK" }
func (p *AdAccountsPipeline) Pipeline() enums.SyncPipelineName {
	return enums.SyncPipelineAdAccounts
}

func (p *AdAccountsPipeline) Run(ctx context.Context, in pipelines.RunInput, publisher pipelines.ExternalEventPublisher) (pipelines.RunResult, error) {
	accessToken := in.Credentials["accessToken"]
	advertiserID := in.Credentials["advertiserId"]

	if accessToken == "" {
		return pipelines.RunResult{Succeeded: false, ErrorMsg: "tiktok credential 'accessToken' is missing"},
			fmt.Errorf("tiktok ad_accounts: accessToken required")
	}
	if advertiserID == "" {
		return pipelines.RunResult{Succeeded: false, ErrorMsg: "tiktok credential 'advertiserId' is missing"},
			fmt.Errorf("tiktok ad_accounts: advertiserId required")
	}

	client := tiktoksvc.NewClient(tiktoksvc.ClientConfig{})

	// Resolve advertiser info (may fetch from API if not in credentials).
	advertiserInfo := tiktoksvc.AdvertiserInfoFromCredentials(advertiserID, in.Credentials)
	if advertiserInfo == nil {
		var err error
		advertiserInfo, err = client.GetAdvertiserInfo(ctx, accessToken, advertiserID)
		if err != nil {
			return pipelines.RunResult{Succeeded: false, ErrorMsg: err.Error()},
				fmt.Errorf("tiktok ad_accounts: GetAdvertiserInfo: %w", err)
		}
	}

	input := entities.AdAccountInput{
		Platform:                  "TIKTOK",
		ExternalID:                advertiserID,
		BusinessAccountExternalID: advertiserID, // advertiser is its own BM on TikTok
		Name:                      advertiserID,
		Currency:                  advertiserInfo.Currency,
		Timezone:                  advertiserInfo.Timezone,
		Status:                    "ACTIVE",
		ExternalCreatedAt:         time.Time{},
	}

	// 1. Emit domain event → handler persists the aggregate.
	evt := events.NewExternalAdAccountUpdated(input, in.StoreID)
	if err := publisher.Publish(ctx, evt); err != nil {
		return pipelines.RunResult{Succeeded: false, ErrorMsg: err.Error()},
			fmt.Errorf("tiktok ad_accounts: publish domain event: %w", err)
	}

	// 2. Publish wire discovery event for TS link table (Spec β.2).
	discoveryEvt := buildTikTokAdAccountDiscoveryEvent(in, advertiserInfo)
	if in.Mediator != nil {
		if pubErr := in.Mediator.Publish(ctx, discoveryEvt); pubErr != nil {
			// Non-fatal — domain event already persisted.
			_ = pubErr
		}
	}

	return pipelines.RunResult{RowsTouched: 1, Succeeded: true}, nil
}

func buildTikTokAdAccountDiscoveryEvent(in pipelines.RunInput, info *tiktoksvc.AdvertiserInfo) types.IntegrationEvent[wire.MarketingAdAccountDiscoveredEvent] {
	currency, _ := wire.ParseCurrencyCode(info.Currency)
	payload := wire.MarketingAdAccountDiscoveredEvent{
		Name:                       wire.MarketingAdAccountDiscoveredEventName,
		OwnerID:                    in.StoreID,
		OccurredAt:                 time.Now().UTC(),
		Platform:                   wire.MarketingPlatformTIKTOK,
		AdAccountExternalID:        info.AdvertiserID,
		BusinessAccountExternalID:  info.AdvertiserID,
		AccountName:                info.AdvertiserID,
		StoreIntegrationExternalID: in.StoreIntegrationExternalID,
		Currency:                   currency,
	}
	return types.NewIntegrationEvent(wire.MarketingAdAccountDiscoveredEventName, in.StoreID, payload)
}

// compile-time check
var _ pipelines.Pipeline = (*AdAccountsPipeline)(nil)

// Package tiktok contains the TikTok Marketing API HTTP client,
// normalizers, receivers, and sync orchestrator for the TIKTOK sync pipelines.
package tiktok

// Credentials for TikTok Ads API.
type Credentials struct {
	AccessToken  string `json:"accessToken" validate:"required"`
	AdvertiserID string `json:"advertiserId" validate:"required"`
}

// TikTokInsight represents a single insight row from the API.
type TikTokInsight struct {
	CampaignID   string // from dimensions.campaign_id
	StatTimeHour string // from dimensions.stat_time_hour (hourly only)
	StatTimeDay  string // from dimensions.stat_time_day (daily only)
	Spend        string // from metrics.spend
	Currency     string // from metrics.currency
}

// InsightsResponse is the top-level API response for the integrated report endpoint.
type InsightsResponse struct {
	Code    int                  `json:"code"`
	Message string               `json:"message"`
	Data    InsightsResponseData `json:"data"`
}

// InsightsResponseData wraps the paginated list of insight rows.
type InsightsResponseData struct {
	List     []InsightRow `json:"list"`
	PageInfo PageInfo     `json:"page_info"`
}

// InsightRow is a single row from the insights API (dimensions + metrics).
type InsightRow struct {
	Dimensions InsightDimensions `json:"dimensions"`
	Metrics    InsightMetrics    `json:"metrics"`
}

