}

// AdvertiserInfo contains account-level metadata for an advertiser.
type AdvertiserInfo struct {
	AdvertiserID string
	Currency     string
	Timezone     string
}

// AdvertiserInfoFromCredentials builds AdvertiserInfo from credential values.
// Returns nil if currency or timezone are missing (caller must fetch from API).
func AdvertiserInfoFromCredentials(advertiserID string, credentials map[string]string) *AdvertiserInfo {
	currency := credentials["currency"]
	timezone := credentials["timezone"]
	if currency == "" || timezone == "" {
		return nil
	}
	return &AdvertiserInfo{
		AdvertiserID: advertiserID,
		Currency:     currency,
		Timezone:     timezone,
	}
}

// AdvertiserResponse is the top-level API response for the advertiser/info endpoint.
