// AdvertiserResponseData wraps the list of advertiser data.
type AdvertiserResponseData struct {
	List []AdvertiserData `json:"list"`
}

// AdvertiserData is the raw API shape for a single advertiser.
type AdvertiserData struct {
	AdvertiserID   string `json:"advertiser_id"`
	AdvertiserName string `json:"advertiser_name"`
	Currency       string `json:"currency"`
	Timezone       string `json:"timezone"`
}

// TikTokCampaign is the raw API shape for a campaign from the campaign/get endpoint.
type TikTokCampaign struct {
	CampaignID      string `json:"campaign_id"`
	CampaignName    string `json:"campaign_name"`
	OperationStatus string `json:"operation_status"`
	CreateTime      string `json:"create_time"`
}

// CampaignsList is the data section of the campaigns API response.
type CampaignsList struct {
	List     []TikTokCampaign `json:"list"`
	PageInfo struct {
		TotalNumber int `json:"total_number"`
		Page        int `json:"page"`
		PageSize    int `json:"page_size"`
		TotalPage   int `json:"total_page"`
	} `json:"page_info"`
}

// CampaignsResponse is the top-level API response for the campaign/get endpoint.
type CampaignsResponse struct {
	Code int           `json:"code"`
	Msg  string        `json:"message"`
	Data CampaignsList `json:"data"`
}

