import { PrismaService } from "@infra";
import {
	BadRequestException,
	ConflictException,
	Injectable,
	InternalServerErrorException,
} from "@nestjs/common";
import { JwtService } from "@nestjs/jwt";
import { convertTZToTimezoneName, getTimezoneOffset } from "@shared/mappers";
import { TimezoneName } from "@shared/types";
import { TraceClass } from "@utils/tracing";
import { differenceInSeconds } from "date-fns";
import { Customer, enums, GoogleAdsApi, resources, services } from "google-ads-api";
import { google } from "googleapis";
import {
	Currency,
	MarketingPlatformAdAccount,
	MarketingPlatformBusinessAccount,
	PlatformAccountInfo,
} from "sql";
import { LoggerService } from "~/modules/logger/logger.service";
import { CreateMarketingPlatformAdAccountDto } from "../dto/createMarketingPlatformAdAccount.dto";
import { CreateMarketingPlatformBusinessAccount } from "../dto/createMarketingPlatformBusinessAccount.dto";
import { CreatePlatformAccountInfoDto } from "../dto/createPlatformAccountInfo.dto";
import { OAuthService } from "../oauth.service";
import { AuthGoogleAccountDto } from "./dto/authGoogleAccount.dto";
import { CredentialsGoogleAccountDto } from "./dto/credentialsGoogleAccount.dto";

interface AdAccount {
	id: string;
	name: string;
	currency: Currency;
	timezone: string;
	isManager: false;
	level: number;
	description: string;
	managerId: string | null;
	status: string;
}

interface ManagerAccount {
	id: string;
	name: string;
	isManager: true;
	level: number;
	description: string;
	currency: Currency;
	timezone: string;
	status: string;
}

@Injectable()
@TraceClass()
export class GoogleAuthService implements OAuthService {
	private googleAdsClient!: GoogleAdsApi;
	private currentRefreshToken: string | null = null;
	private adAccounts: Record<string, Map<string, AdAccount>>;
	private managerAccounts: Record<string, Map<string, ManagerAccount>>;

	constructor(
		private readonly jwtService: JwtService,
		private readonly prismaService: PrismaService,
		private readonly logger: LoggerService,
	) {
		this.adAccounts = {};
		this.managerAccounts = {};
	}

	async getAccessToken(code: string): Promise<CredentialsGoogleAccountDto> {
		if (
			!process.env.GOOGLE_CLIENT_ID ||
			!process.env.GOOGLE_CLIENT_SECRET ||
			!process.env.GOOGLE_REDIRECT_URL ||
			!process.env.GOOGLE_ADS_DEVELOPER_TOKEN
		) {
			throw new InternalServerErrorException("Missing google environment variables!");
		}

		const oauth2Client = new google.auth.OAuth2(
			process.env.GOOGLE_CLIENT_ID,
			process.env.GOOGLE_CLIENT_SECRET,
			process.env.GOOGLE_REDIRECT_URL,
		);

		const { tokens } = await oauth2Client.getToken(code);

		oauth2Client.setCredentials(tokens);
		google.options({ auth: oauth2Client });

		this.setCurrentRefreshToken(tokens.refresh_token ?? null);

		const { email, sub } = this.jwtService.decode(tokens.id_token!);

		this.googleAdsClient = new GoogleAdsApi({
			client_id: process.env.GOOGLE_CLIENT_ID!,
			client_secret: process.env.GOOGLE_CLIENT_SECRET!,
			developer_token: process.env.GOOGLE_ADS_DEVELOPER_TOKEN!,
		});

		const encryptedToken = this.jwtService.sign(
			{
				accessToken: tokens.access_token,
				email,
				refreshToken: tokens.refresh_token,
				sub, // Google User ID (externalId)
			},
			{
				expiresIn: differenceInSeconds(tokens.expiry_date!, new Date()),
			},
		);

		return {
			accessToken: encryptedToken,
			expireAt: new Date(tokens.expiry_date!),
		};
	}

	async getUserInfo(accessToken: string): Promise<{ email: string; externalId: string }> {
		const { email, sub } = this.jwtService.decode(accessToken);
		return { email, externalId: sub };
	}

	async addAccountInfo(
		integrationSetHasMarketingPlatformId: string,
		email: string,
	): Promise<Partial<PlatformAccountInfo>> {
		const people = google.people("v1");

		const { data } = await people.people.get({
			personFields: "emailAddresses,names,photos",
			resourceName: "people/me",
		});

		const connectedAccount = await this.getGoogleAccountInfoByEmail(
			integrationSetHasMarketingPlatformId,
			email,
		);

		if (connectedAccount) {
			return connectedAccount;
		}

		return this.create({
			email,
			integrationSetHasMarketingPlatformId,
			name: data.names?.[0]?.displayName ?? email,
			pictureUrl: data.photos?.[0]?.url || "",
		});
	}

async addAdAccounts(
	integrationSetHasMarketingPlatformId: string,
): Promise<Partial<MarketingPlatformAdAccount>[]> {
	this.adAccounts[integrationSetHasMarketingPlatformId] = new Map<string, AdAccount>();
	this.managerAccounts[integrationSetHasMarketingPlatformId] = new Map<string, ManagerAccount>();

	if (!this.googleAdsClient) {
		throw new InternalServerErrorException("Google Ads client not initialized");
	}

	try {
		const accessibleCustomers = await this.googleAdsClient.listAccessibleCustomers(
			this.getCurrentRefreshToken(),
		);

		this.logger.info({
			content: {
				message: `Retrieving accessible customers: ${accessibleCustomers?.resource_names}`,
			},
		});

		if (!accessibleCustomers?.resource_names || accessibleCustomers.resource_names.length === 0) {
			throw new BadRequestException("No accessible customers found for the user.");
		}

		await this.applyAllAccounts(integrationSetHasMarketingPlatformId, this.getCurrentRefreshToken());

		// Create business account's database records

		const businessAccountsPromiseList: Promise<Partial<MarketingPlatformBusinessAccount>>[] = [];

		for (const managerAccount of this.managerAccounts[integrationSetHasMarketingPlatformId].values()) {
			const businessAccountsPromise = this.upsertBusinessAccount({
				active: managerAccount.status?.toString() === enums.CustomerStatus.ENABLED.toString(),
				externalId: managerAccount.id,
				integrationSetHasMarketingPlatformId,
				link: "",
				name: managerAccount.name,
			});

			businessAccountsPromiseList.push(businessAccountsPromise);
		}

		const businessAccountsResults: Partial<MarketingPlatformBusinessAccount>[] = [];
		try {
			this.logger.info({
				content: {
					message: `Creating business accounts for integrationSetHasMarketingPlatformId: ${integrationSetHasMarketingPlatformId}`,
				},
			});
			const results = await Promise.all(businessAccountsPromiseList);
			businessAccountsResults.push(...results);
		} catch (_error) {
			this.logger.error({
				content: {
					message: `Error creating business accounts for integrationSetHasMarketingPlatformId: ${integrationSetHasMarketingPlatformId}`,
				},
			});
		}

		const adAccountPromiseList: Promise<Partial<MarketingPlatformAdAccount>>[] = [];

		for (const adAccount of this.adAccounts[integrationSetHasMarketingPlatformId].values()) {
			// Convert timezone to IANA format and fetch offset
			let timezoneOffset: string | undefined;
			if (adAccount.timezone) {
				try {
					// Check if it's in TZ format (starts with TZ_) or already IANA format
					const ianaTimezone: string | undefined = adAccount.timezone.startsWith("TZ_")
						? convertTZToTimezoneName(adAccount.timezone as any)
						: adAccount.timezone;

					if (ianaTimezone) {
						timezoneOffset = getTimezoneOffset(ianaTimezone as TimezoneName);
					}
				} catch (error) {
					this.logger.warn({
						content: {
							message: `Failed to fetch timezone offset for ${adAccount.timezone}: ${error}`,
						},
					});
				}
			}

			const adAccountPromise = this.upsertAdAccount({
				active: adAccount.status?.toString() === enums.CustomerStatus.ENABLED.toString(),
				businessAccountId:
					businessAccountsResults.find(
						businessAccount => businessAccount.externalId === adAccount.managerId,
					)?.id ?? null,
				currency: adAccount.currency,
				externalId: adAccount.id,
				integrationSetHasMarketingPlatformId,
				name: adAccount.name,
				timezone: adAccount.timezone,
				timezoneOffset,
			});

			adAccountPromiseList.push(adAccountPromise);
		}

		const adAccountsResults: Partial<MarketingPlatformAdAccount>[] = [];
		try {
			this.logger.info({
				content: {
					message: `Creating ad accounts for integrationSetHasMarketingPlatformId: ${integrationSetHasMarketingPlatformId}`,
				},
			});
			const results = await Promise.all(adAccountPromiseList);
			adAccountsResults.push(...results);
		} catch (_error) {
			this.logger.error({
				content: {
					message: `Error creating ad accounts for integrationSetHasMarketingPlatformId: ${integrationSetHasMarketingPlatformId}`,
				},
			});
		}

		return adAccountsResults;
	} catch (error: any) {
		console.error("Error fetching Google Ads accounts:", error);

		// Re-throw specific NestJS exceptions as-is
		if (error instanceof BadRequestException || error instanceof ConflictException) {
			throw error;
		}

		throw new InternalServerErrorException(`Google Ads API Error: ${error.message}`);
	} finally {
		delete this.adAccounts[integrationSetHasMarketingPlatformId];
		delete this.managerAccounts[integrationSetHasMarketingPlatformId];
	}
}

async auth(
	integrationSetHasMarketingPlatformId: string,
	credentials: CredentialsGoogleAccountDto,
): Promise<AuthGoogleAccountDto> {
	const token = await this.jwtService.decode(credentials.accessToken);

	// Check if all credentials are available
	if (!token?.accessToken || !token.refreshToken) {
		throw new BadRequestException("missing JWT credentials!");
	}

	// Check if all environment variables are set
	if (
		!process.env.GOOGLE_CLIENT_ID ||
		!process.env.GOOGLE_CLIENT_SECRET ||

import { PrismaService } from "@infra";
import { HttpService } from "@nestjs/axios";
import {
	BadRequestException,
	HttpException,
	Injectable,
	InternalServerErrorException,
	Scope,
} from "@nestjs/common";
import { EventEmitter2 } from "@nestjs/event-emitter";
import { JwtService } from "@nestjs/jwt";
import { FACEBOOK_URL_TOKEN } from "@utils";
import { TraceClass } from "@utils/tracing";
import { addSeconds } from "date-fns";
import { AdAccount, FacebookAdsApi, User } from "facebook-nodejs-business-sdk";
import { catchError, firstValueFrom, map } from "rxjs";
import {
	Currency,
	MarketingPlatformAdAccount,
	MarketingPlatformBusinessAccount,
	PlatformAccountInfo,
} from "sql";
import { NotificationOrigin, NotificationType } from "~/modules/notifications/events/enum";
import { NotificationEvent } from "~/modules/notifications/events/notificationEvent";
import { CreateMarketingPlatformAdAccountDto } from "../dto/createMarketingPlatformAdAccount.dto";
import { CreateMarketingPlatformBusinessAccount } from "../dto/createMarketingPlatformBusinessAccount.dto";
import { CreatePlatformAccountInfoDto } from "../dto/createPlatformAccountInfo.dto";
import { OAuthService } from "../oauth.service";
import { AuthFacebookAccountDto } from "./dto/authFacebookAccount.dto";
import { CredentialsFacebookAccountDto } from "./dto/credentialsFacebookAccount.dto";

@Injectable({
	scope: Scope.REQUEST,
})
@TraceClass()
export class FacebookAuthService implements OAuthService {
	private api!: FacebookAdsApi;

	constructor(
		private readonly jwtService: JwtService,
		private readonly prismaService: PrismaService,
		private readonly httpService: HttpService,
		private readonly eventEmitter: EventEmitter2,
	) {}

	async getAccessToken(token: string): Promise<CredentialsFacebookAccountDto> {
		const { accessToken, expiresAt } = await this.fetchFacebookLongToken(token);

		this.api = FacebookAdsApi.init(accessToken);

		let accountInfo: Partial<{ email: string; name: string }> = {};
		let userId: string | null = null;

		try {
			accountInfo = await new User("me", {}, null, this.api).read([
				User.Fields.email,
				User.Fields.name,
				User.Fields.id,
			]);
			userId = (accountInfo as any).id;
		} catch (error) {
			console.error("Error fetching account info from Facebook:", error);

			// Try to get at least the user ID as fallback
			try {
				const basicInfo = await new User("me", {}, null, this.api).read([User.Fields.id]);
				userId = basicInfo.id;
				console.log("Facebook user ID obtained as fallback:", userId);
			} catch (fallbackError) {
				console.error("Error fetching basic user info from Facebook:", fallbackError);
			}
		}

		// Use email from account info or generate a fallback based on user ID
		// This ensures consistent identification even if Facebook doesn't provide email
		const email =
			accountInfo.email ||
			(userId
				? `facebook_user_${userId}@facebook.placeholder`
				: `facebook_user_${Date.now()}@facebook.placeholder`);

		const encryptedToken = this.jwtService.sign({
			accessToken,
			email,
			id: userId,
		});

		return {
			accessToken: encryptedToken,
			expireAt: expiresAt,
		};
	}

	async getUserInfo(accessToken: string): Promise<{ email: string; externalId: string }> {
		const { email, id } = await this.jwtService.decode(accessToken);

		return { email, externalId: id };
	}

	async addAccountInfo(
		integrationSetHasMarketingPlatformId: string,
		email: string,
	): Promise<Partial<PlatformAccountInfo>> {
		let accountInfo: Partial<{ name: string; id: string }> = {};
		let userId: string | null = null;

		try {
			accountInfo = await new User("me", {}, null, this.api).read([User.Fields.name, User.Fields.id]);
			userId = accountInfo.id || null;
		} catch (error) {
			console.error("Error fetching account info from Facebook:", error);

			// Try to get at least the user ID as fallback
			try {
				const basicInfo = await new User("me", {}, null, this.api).read([User.Fields.id]);
				userId = basicInfo.id;
				console.log("Facebook user ID obtained as fallback in addAccountInfo:", userId);
			} catch (fallbackError) {
				console.error("Error fetching user ID from Facebook:", fallbackError);
			}
		}

		const connectedAccount = await this.getFacebookAccountInfoByEmail(
			integrationSetHasMarketingPlatformId,
			email,
		);

		if (connectedAccount) {
			return connectedAccount;
		}

		// Generate better fallback values for missing information
		// Priority: 1) Use current session user ID, 2) Extract from placeholder email, 3) Generic fallback
		let fallbackUserId = userId;
		if (!fallbackUserId && email.includes("@facebook.placeholder")) {
			// Extract user ID from previously created placeholder email (facebook_user_123456@facebook.placeholder)
			const match = email.match(/facebook_user_(\d+)@/);
			fallbackUserId = match ? match[1] : null;
		}

		const fallbackName =
			accountInfo?.name ||
			(fallbackUserId
				? `Facebook User (${fallbackUserId})`
				: email.includes("@facebook.placeholder")
					? "Facebook User"
					: `Facebook User (${email.split("@")[0]})`);

		return this.create({
			email,
			integrationSetHasMarketingPlatformId,
			name: fallbackName,
			pictureUrl: null,
		});
	}

	async addAdAccounts(
		integrationSetHasMarketingPlatformId: string,
	): Promise<Partial<MarketingPlatformAdAccount>[]> {
		const user = new User("me", {}, null, this.api);

		// Fetch all ad accounts with pagination
		const allAdAccounts = await this.getAllAdAccountsPaginated(user);

		if (!allAdAccounts || allAdAccounts.length === 0) {
			throw new BadRequestException("No ad accounts found for the user.");
		}
		const result: Partial<{
			currency: string;
			id: string;
			name: string;
			integrationSetHasMarketingPlatformId: string;
			createdAt: Date;
			updatedAt: Date;
			disabledAt: Date | null;
			externalId: string;
			active: boolean;
			lastSyncAt: Date;
			businessAccountId: string | null;
		}>[] = [];

		for (const adAccount of allAdAccounts) {
			const existingAccount = await this.prismaService.marketingPlatformAdAccount.findFirst({
				where: {
					externalId: adAccount.id,
					integrationSetHasMarketingPlatformId,
				},
			});

			let marketingPlatformBusinessAccountId: string | null = null;

			if (adAccount.business) {
				const existingBusinessAccount = await this.prismaService.marketingPlatformBusinessAccount.findFirst({
					where: {
						externalId: adAccount.business.id,
						integrationSetHasMarketingPlatformId,
					},
				});

				const upsertedBusiness = await this.upsertBusinessAccount({

			const upsertedBusiness = await this.upsertBusinessAccount({
				...adAccount.business,
				active: existingBusinessAccount?.active || true,
				externalId: adAccount.business.id,
				integrationSetHasMarketingPlatformId,
			});

			marketingPlatformBusinessAccountId = upsertedBusiness.id!;
		}

		const upsertedAdAccount = await this.upsertAdAccount({
			active: existingAccount?.active || true,
			businessAccountId: marketingPlatformBusinessAccountId,
			currency: this.convertFacebookCurrencyToLocal(adAccount.currency),
			externalId: adAccount.id,
			integrationSetHasMarketingPlatformId,
			name: adAccount.name,
			timezone: adAccount.timezone_name,
			timezoneOffset: adAccount.timezone_offset,
		});

		result.push(upsertedAdAccount);
	}

	return result;
}

async auth(
	_integrationSetHasMarketingPlatformId: string,
	credentials: CredentialsFacebookAccountDto,
): Promise<AuthFacebookAccountDto> {
	const token = await this.jwtService.decode(credentials.accessToken);

	try {
		FacebookAdsApi.init(token.accessToken).setShowHeader(true);
		new User("me", {}, null, this.api);
	} catch (error: any) {
		if (error.response?.error) {
			const fbError = error.response.error;
			if (fbError.code === 190) {
				if (fbError.error_subcode === 463) {
					const event = new NotificationEvent(
						NotificationType.QUICK,
						"Access token has expired",
						"text/plain",
						NotificationOrigin.DASH,
						"FACEBOOK_TOKEN_EXPIRED",
						true,
					);

					this.eventEmitter.emit(event.name, event);
					throw new BadRequestException("Access token has expired");
				}
				throw new BadRequestException("Invalid access token");
			}
		}
		throw new InternalServerErrorException(`Facebook API Error: ${error.message}`);
	}

	delete token.accessToken;

	return token;
}

private async fetchFacebookLongToken(token: string) {
	const params = {
		client_id: process.env.FACEBOOK_CLIENT_ID,
