Maps every IANA timezone identifier to its UTC offset (standard time, no DST).

#### b. Get Timezone Offset (lines 409-426)
```typescript
export function getTimezoneOffset(timezoneName: TimezoneName, number: true): number;
export function getTimezoneOffset(timezoneName: TimezoneName, number?: false): TimezoneOffsetString;
export function getTimezoneOffset(timezoneName: TimezoneName, number = false): TimezoneOffsetString | number {
    const offset = timezoneOffsetMap[timezoneName];
    if (!offset) {
        return timezoneOffsetMap["America/Sao_Paulo"]; // Fallback default
    }

    if (number) {
        return Number(offset.slice(0, -3)); // Returns hours as number (e.g., -3 for "-03:00")
    }

    return offset; // Returns string like "-03:00"
