package objects

import (
	"strings"

	wire "template/contracts-go/wire"
)

// DefaultTimezone is the canonical fallback used when a provider sends an
// empty or unrecognised timezone. UTC is the neutral anchor — reporting
// callers can re-localise from it rather than from a guessed region.
const DefaultTimezone = wire.TimezoneUTC

// NormalizeTimezone coerces a provider-supplied timezone into the canonical
// wire.Timezone enum (IANA tz database identifiers). Providers disagree on
// format:
//
//   - Facebook (`timezone_name`) and TikTok (`timezone`) send IANA names
//     directly ("America/Sao_Paulo") — validated as-is.
//   - Google Ads can surface the legacy `TZ_*` enum form
//     ("TZ_AMERICA_SAO_PAULO"); we map those back to IANA first — mirroring
//     the tz->IANA conversion bk-dash-backend performs — before validating.
//
// Anything empty or outside the supported zone set collapses to
// DefaultTimezone rather than erroring: an unknown timezone is a reporting
// nuisance, not a reason to reject an entire ad-account sync.
func NormalizeTimezone(raw string) wire.Timezone {
	s := strings.TrimSpace(raw)
	if s == "" {
		return DefaultTimezone
	}
	if strings.HasPrefix(s, "TZ_") {
		if iana, ok := tzLegacyToIANA[s]; ok {
			s = iana
		}
	}
	tz, err := wire.ParseTimezone(s)
	if err != nil {
		return DefaultTimezone
	}
	return tz
}

