func TestNormalizeTimezone(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want wire.Timezone
	}{
		{"iana facebook/tiktok passthrough", "America/Sao_Paulo", wire.TimezoneAMERICA_SAO_PAULO},
		{"iana with surrounding whitespace", "  Europe/London  ", wire.TimezoneEUROPE_LONDON},
		{"google legacy TZ_ form", "TZ_AMERICA_NEW_YORK", wire.TimezoneAMERICA_NEW_YORK},
		{"google legacy TZ_ nested zone", "TZ_AMERICA_ARGENTINA_BUENOS_AIRES", wire.TimezoneAMERICA_ARGENTINA_BUENOS_AIRES},
		{"empty falls back to default", "", DefaultTimezone},
		{"blank falls back to default", "   ", DefaultTimezone},
		{"unknown iana falls back to default", "Mars/Olympus_Mons", DefaultTimezone},
		{"unknown TZ_ falls back to default", "TZ_NOWHERE", DefaultTimezone},
		{"utc passthrough", "UTC", wire.TimezoneUTC},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := NormalizeTimezone(tc.in); got != tc.want {
				t.Errorf("NormalizeTimezone(%q) = %q, want %q", tc.in, got, tc.want)
			}
		})
	}
}

