		{"google legacy TZ_ form", "TZ_AMERICA_NEW_YORK", wire.TimezoneAMERICA_NEW_YORK},
		{"empty falls back to UTC", "", wire.TimezoneUTC},
		{"unrecognised falls back to UTC", "Middle/Earth", wire.TimezoneUTC},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			in := validAdAccountInput()
			in.Timezone = tc.timezone
			a, err := NewAdAccountFromProviderPayload(in)
			if err != nil {
