func validAdAccountInput() AdAccountInput {
	return AdAccountInput{
		Platform:                  string(wire.MarketingPlatformMETA),
		ExternalID:                "aa_meta_001",
		BusinessAccountExternalID: "ba_meta_001",
		Name:                      "Acme Ad Account",
		Currency:                  string(wire.CurrencyCodeBRL),
		Timezone:                  "America/Sao_Paulo",
		Status:                    string(wire.AdAccountStatusACTIVE),
		ExternalCreatedAt:         time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC),
	}
}

func TestNewAdAccountFromProviderPayload_ValidInput(t *testing.T) {
	a, err := NewAdAccountFromProviderPayload(validAdAccountInput())
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if a == nil {
		t.Fatal("expected non-nil AdAccount")
	}
	if a.ID().Value() == "" {
		t.Error("ID should not be empty")
	}
	if a.Platform() != wire.MarketingPlatformMETA {
		t.Errorf("Platform = %q, want META", a.Platform())
	}
	if a.Currency() != wire.CurrencyCodeBRL {
		t.Errorf("Currency = %q, want BRL", a.Currency())
	}
	if a.Status() != wire.AdAccountStatusACTIVE {
		t.Errorf("Status = %q, want ACTIVE", a.Status())
	}
}

func TestNewAdAccountFromProviderPayload_MissingRequiredFields(t *testing.T) {
	cases := []struct {
		name    string
		mutate  func(*AdAccountInput)
		wantErr error
	}{
		{
			name:    "missing platform",
			mutate:  func(in *AdAccountInput) { in.Platform = "" },
			wantErr: ErrAdAccountMissingPlatform,
		},
		{
			name:    "blank platform",
			mutate:  func(in *AdAccountInput) { in.Platform = "  " },
			wantErr: ErrAdAccountMissingPlatform,
		},
		{
			name:    "missing externalID",
			mutate:  func(in *AdAccountInput) { in.ExternalID = "" },
			wantErr: ErrAdAccountMissingExternalID,
		},
		{
			name:    "blank externalID",
			mutate:  func(in *AdAccountInput) { in.ExternalID = "  " },
			wantErr: ErrAdAccountMissingExternalID,
		},
		{
			name:    "invalid platform",
			mutate:  func(in *AdAccountInput) { in.Platform = "BEBO" },
			wantErr: ErrAdAccountInvalidPlatform,
		},
		{
			name:    "invalid currency",
			mutate:  func(in *AdAccountInput) { in.Currency = "MOONBEAMS" },
			wantErr: ErrAdAccountInvalidCurrency,
		},
		{
			name:    "invalid status",
			mutate:  func(in *AdAccountInput) { in.Status = "LIMBO" },
			wantErr: ErrAdAccountInvalidStatus,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			in := validAdAccountInput()
			tc.mutate(&in)
			_, err := NewAdAccountFromProviderPayload(in)
			if !errors.Is(err, tc.wantErr) {
				t.Errorf("got %v, want %v", err, tc.wantErr)
			}
		})
	}
}

func TestNewAdAccountFromProviderPayload_Idempotency(t *testing.T) {
	a, err := NewAdAccountFromProviderPayload(validAdAccountInput())
	if err != nil {
		t.Fatalf("first call: %v", err)
	}
	b, err := NewAdAccountFromProviderPayload(validAdAccountInput())
	if err != nil {
		t.Fatalf("second call: %v", err)
	}
	if a.ID().Value() != b.ID().Value() {
		t.Errorf("ID not deterministic: %s != %s", a.ID().Value(), b.ID().Value())
	}
}

