package entities

import (
	"errors"
	"fmt"
	"strings"
	"time"

	"template/api-go/internal/sync/objects"
	wire "template/contracts-go/wire"
	coreobjects "template/core-go/objects"
)

// AdAccount is the canonical marketing ad-account aggregate. An ad account
// belongs to a business account and is the billing and campaign container
// on a given marketing platform.
type AdAccount struct {
	id                        coreobjects.ID
	platform                  wire.MarketingPlatform
	externalID                string
	businessAccountExternalID string
	name                      string
	currency                  wire.CurrencyCode
	timezone                  wire.Timezone
	status                    wire.AdAccountStatus
	externalCreatedAt         time.Time
}

// AdAccountInput is the normalised provider data the per-platform
// normaliser produces. The aggregate validates this before the UPSERT.
type AdAccountInput struct {
	Platform                  string
	ExternalID                string
	BusinessAccountExternalID string
	Name                      string
	Currency                  string
	// Timezone is the raw provider value (Facebook timezone_name, Google
	// customer.time_zone, TikTok timezone). The aggregate normalises it to
	// the canonical wire.Timezone enum via objects.NormalizeTimezone.
	Timezone          string
	Status            string
	ExternalCreatedAt time.Time
}

var (
	ErrAdAccountMissingExternalID = errors.New("ad_account: externalId required")
	ErrAdAccountMissingPlatform   = errors.New("ad_account: platform required")
	ErrAdAccountInvalidPlatform   = errors.New("ad_account: invalid platform")
	ErrAdAccountInvalidCurrency   = errors.New("ad_account: invalid currency")
	ErrAdAccountInvalidStatus     = errors.New("ad_account: invalid status")
)

// NewAdAccountFromProviderPayload validates + constructs the canonical
// AdAccount aggregate.
func NewAdAccountFromProviderPayload(in AdAccountInput) (*AdAccount, error) {
	if strings.TrimSpace(in.Platform) == "" {
		return nil, ErrAdAccountMissingPlatform
	}
	if strings.TrimSpace(in.ExternalID) == "" {
		return nil, ErrAdAccountMissingExternalID
	}

	platform, err := wire.ParseMarketingPlatform(in.Platform)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrAdAccountInvalidPlatform, err)
	}
	currency, err := wire.ParseCurrencyCode(in.Currency)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrAdAccountInvalidCurrency, err)
	}
	status, err := wire.ParseAdAccountStatus(in.Status)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrAdAccountInvalidStatus, err)
	}

	id, err := coreobjects.IDFromSeed(string(platform), in.ExternalID)
	if err != nil {
		return nil, fmt.Errorf("ad_account: id derivation: %w", err)
	}

	return &AdAccount{
		id:                        id,
		platform:                  platform,
		externalID:                in.ExternalID,
		businessAccountExternalID: in.BusinessAccountExternalID,
		name:                      in.Name,
		currency:                  currency,
		timezone:                  objects.NormalizeTimezone(in.Timezone),
		status:                    status,
		externalCreatedAt:         in.ExternalCreatedAt,
	}, nil
}

// Accessors
func (a *AdAccount) ID() coreobjects.ID                { return a.id }
func (a *AdAccount) Platform() wire.MarketingPlatform  { return a.platform }
func (a *AdAccount) ExternalID() string                { return a.externalID }
func (a *AdAccount) BusinessAccountExternalID() string { return a.businessAccountExternalID }
func (a *AdAccount) Name() string                      { return a.name }
func (a *AdAccount) Currency() wire.CurrencyCode       { return a.currency }
func (a *AdAccount) Timezone() wire.Timezone           { return a.timezone }
func (a *AdAccount) Status() wire.AdAccountStatus      { return a.status }
func (a *AdAccount) ExternalCreatedAt() time.Time      { return a.externalCreatedAt }

